INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷79·晋高祖纪·天福五年八月及后续条目", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c3ae4917b03ca0346efedf03bafabb5e360d93ab/content/books/zizhi-tongjian/vol-282/year-0940/part-03/sources/library/jiuwudaishi-079-august-autumn/source.txt", "note": "《旧五代史》卷79·晋高祖纪·天福五年八月及后续条目，段落 jiu-wudaishi-205deb4a7860-p001948；已核上下文及传主，纸本及异文待核。", "id": "7bd43002-613a-594a-95cd-0770443b2ee8"}, {"title": "旧五代史·卷79·晋高祖纪·天福五年十一月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c3ae4917b03ca0346efedf03bafabb5e360d93ab/content/books/zizhi-tongjian/vol-282/year-0940/part-03/sources/library/jiuwudaishi-079-november/source.txt", "note": "《旧五代史》卷79·晋高祖纪·天福五年十一月，段落 jiu-wudaishi-205deb4a7860-p001950；已核上下文及传主，纸本及异文待核。", "id": "bf52de56-f4dc-5545-80af-20fc66114b34"}, {"title": "旧五代史·卷79·晋高祖纪·天福五年十月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c3ae4917b03ca0346efedf03bafabb5e360d93ab/content/books/zizhi-tongjian/vol-282/year-0940/part-03/sources/library/jiuwudaishi-079-october/source.txt", "note": "《旧五代史》卷79·晋高祖纪·天福五年十月，段落 jiu-wudaishi-205deb4a7860-p001949；已核上下文及传主，纸本及异文待核。", "id": "5367b9bf-fffd-5e0d-b732-57745d65154a"}, {"title": "宋史·卷262·李涛附李澣传·任官", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c3ae4917b03ca0346efedf03bafabb5e360d93ab/content/books/zizhi-tongjian/vol-282/year-0940/part-03/sources/library/songshi-262-li-huan-career/source.txt", "note": "《宋史》卷262·李涛附李澣传·任官，段落 songshi-9c6e46fee832-p058128；已核上下文及传主，纸本及异文待核。", "id": "6623fbf4-0dfa-564b-bf0a-1c01ad2b2fe1"}, {"title": "宋史·卷262·李涛传", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7ab11539b383300ef1f618b97db115f4d85186a1/content/books/zizhi-tongjian/vol-281/year-0937/part-05/sources/library/songshi-262-li-tao-age/source.txt", "note": "《宋史》卷262·李涛传，段落 songshi-9c6e46fee832-p058125；已核上下文及传主，纸本及异文待核。", "id": "16dd178a-41c3-5d19-b328-f16bef7a2480"}, {"title": "资治通鉴·卷282·天福五年秋冬", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c3ae4917b03ca0346efedf03bafabb5e360d93ab/content/books/zizhi-tongjian/vol-282/year-0940/part-03/sources/library/tongjian-282-940-autumn-winter/source.txt", "note": "《资治通鉴》卷282·天福五年秋冬，段落 zizhi-tongjian-a63549944a71-p003354；已核上下文及传主，纸本及异文待核。", "id": "67bbc261-6a53-5402-b019-4a8cc37d7ad4"}, {"title": "新五代史·卷51·安重荣传·吐谷浑归附", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c3ae4917b03ca0346efedf03bafabb5e360d93ab/content/books/zizhi-tongjian/vol-282/year-0940/part-03/sources/library/xinwudaishi-051-an-chongrong-tuyuhun/source.txt", "note": "《新五代史》卷51·安重荣传·吐谷浑归附，段落 xin-wudaishi-b08f244b9241-p002001；已核上下文及传主，纸本及异文待核。", "id": "c388217f-0877-51f5-af6e-54670f3732ff"}, {"title": "新五代史·卷51·范延光传·遇害异说", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c3ae4917b03ca0346efedf03bafabb5e360d93ab/content/books/zizhi-tongjian/vol-282/year-0940/part-03/sources/library/xinwudaishi-051-fan-yanguang-death/source.txt", "note": "《新五代史》卷51·范延光传·遇害异说，段落 xin-wudaishi-b08f244b9241-p001990；已核上下文及传主，纸本及异文待核。", "id": "a7c3213c-19cd-5323-9441-ae03a37617a5"}, {"title": "资治通鉴·卷282·天福五年夏秋", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c41515820cdf0fa2e63ec5eb0e14bf77c385f320/content/books/zizhi-tongjian/vol-282/year-0940/part-02/sources/library/tongjian-282-940-summer/source.txt", "note": "《资治通鉴》卷282·天福五年夏秋，段落 zizhi-tongjian-a63549944a71-p003353；已核上下文及传主，纸本及异文待核。", "id": "908167a1-4c93-544d-8f5a-8739bae0d275"}, {"title": "新五代史·卷8·晋本纪·天福五年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c41515820cdf0fa2e63ec5eb0e14bf77c385f320/content/books/zizhi-tongjian/vol-282/year-0940/part-02/sources/library/xinwudaishi-008-tianfu-five/source.txt", "note": "《新五代史》卷8·晋本纪·天福五年，段落 xin-wudaishi-b08f244b9241-p000318；已核上下文及传主，纸本及异文待核。", "id": "a628ad85-ffb6-5417-b386-72e51e501435"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "范延光", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：范延光。", "biography": null, "status": "draft", "id": "6889e460-4b23-5243-9441-b5c3a78da98f"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "刘处让", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘处让。", "biography": null, "status": "draft", "id": "7607f037-c9b6-5f79-b064-81fcfd4ee40d"}, {"name": "杨檀", "aliases": ["楊檀", "杨光远", "楊光遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：杨檀，冀州刺史、反对遣归者。", "biography": null, "status": "draft", "id": "54ec3b10-aece-5189-91a8-84a03c5691a3"}, {"name": "杨承贵", "aliases": ["楊承貴"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杨光远之子。940年受父亲派遣围范延光私宅，逼其自尽，随后把范延光推入河中。《新五代史》相关执行者写杨承勋，姓名异说未裁定，不自动合并。生卒年未载。", "biography": null, "status": "draft", "id": "daf29c5e-0a0a-5cc1-aa88-e64404212a3c"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "和凝", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：和凝，翰林学士、建议者。", "biography": null, "status": "draft", "id": "f4084e8d-6018-5318-8498-525d067ebeda"}, {"name": "李崧", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：李崧。", "biography": null, "status": "draft", "id": "42727c37-29c7-534f-b0f7-900992c16def"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "李澣", "aliases": ["李浣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李涛的弟弟，后晋翰林学士。《资治通鉴》说他多次酒后失当，石敬瑭不喜欢他；940年九月翰林学士职务被撤销、事务归中书舍人。《旧五代史》同期学士名写李浣，另记他调吏部员外郎，保留字形说明。生卒年未载。", "biography": null, "status": "draft", "id": "cc1a8d2a-5333-5d3b-befa-dea7a7c759a6"}, {"name": "李涛（后晋宋初官员）", "aliases": ["李濤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李澣的兄长，后晋至宋初官员。《宋史》记他宋初任兵部尚书，去世时六十四岁，年代与887年已在杨行密军中的同名李涛不相容，本批单独建档。生卒年不凭年龄反推，后续旧库记录需逐条核对。", "biography": null, "status": "draft", "id": "c03574d2-e4e9-5739-be38-c52f0c0de233"}, {"name": "钱传瓘", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“钱氏军队攻取温州，卢佶被杀”中为出征者。", "biography": null, "status": "draft", "id": "6674e6a1-d66d-5e57-af1f-2d98f55021a1"}, {"name": "孙智永", "aliases": ["孫智永"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "为南唐李昪提出占星建议的术士。940年以四星聚斗、相关分野有灾为由，劝李昪巡行东都。灾祸属于他的占星判断，不当作已发生灾害。生卒年未载。", "biography": null, "status": "draft", "id": "95a2ce08-bc20-5734-81b4-f039a69186e4"}, {"name": "陈觉", "aliases": ["陳覺"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：陈觉，海陵人、参与谈议者。", "biography": null, "status": "draft", "id": "8f8c34eb-c238-596f-a688-8b8332b405a1"}, {"name": "褚仁规", "aliases": ["褚仁規"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐泰州刺史。940年因陈觉奏称其贪残，被调任随驾职务。《资治通鉴》说陈觉奏报出于私怨，未记正式查明贪残罪行。生卒年未载。", "biography": null, "status": "draft", "id": "0938a55a-3fe5-5f1e-9d76-f7f520aa9b67"}, {"name": "王延羲", "aliases": ["王曦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国宗室，王继鹏的叔父，曾任左仆射、同平章事。939年被政变军队拥立，自称威武节度使、闽国王，更名王曦，改元永隆。生卒年暂未核实。", "biography": null, "status": "draft", "id": "e706d6ae-56f4-5e44-9d24-f3060ae87cbb"}, {"name": "张延翰", "aliases": ["張延翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴国、南唐官员。原任吴国同平章事，937年十月与张居咏、李建勋一同被任命为南唐同平章事。", "biography": null, "status": "draft", "id": "51662122-1d02-5d49-9bbc-a0324cabb6ff"}, {"name": "赵损（南汉宰相）", "aliases": ["赵损", "趙損"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "赵光裔之子，曾任南汉翰林学士承旨、尚书左丞。赵光裔去世后，刘岩任他为门下侍郎、同平章事；本段未列任官确年。生卒年未载。", "biography": null, "status": "draft", "id": "9111fd3a-3773-5dc0-a465-20b4e6e0d27a"}, {"name": "刘岩", "aliases": ["刘龑", "劉巖", "劉龑", "劉岩", "刘巖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平四年条所见人物：刘岩。", "biography": null, "status": "draft", "id": "3b676280-64ca-5ba9-b78d-c6c5f257a018"}, {"name": "王定保", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉宁远节度使，籍贯南昌。940年赵损去世后任中书侍郎、同平章事，史书接记不逾年也去世；本处未给明确死亡年，不强定为940年。出生年未载。", "biography": null, "status": "draft", "id": "3d04742d-7af8-502d-b4dd-6257aff3ae16"}, {"name": "安重荣", "aliases": ["安重榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安重荣，转投者。", "biography": null, "status": "draft", "id": "7309cd08-206a-5781-8eaa-527f54f64299"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "范延光请求回河阳私宅，石敬瑭批准", "start_year": 940, "end_year": 940, "time_original": "940年范延光遇害以前，具体月日未载", "dynasty": "五代十国", "description": "范延光请求回河阳私宅，石敬瑭批准。", "phases": [], "location_name": "河阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e7330ce7-e91c-5e91-9e08-033ab1cd3c34"}, {"title": "刘处让以契丹追索的说法劝范延光离京", "start_year": null, "end_year": null, "time_original": "范延光退休后离京以前，《新五代史》未给明确年月", "dynasty": "五代十国", "description": "《新五代史》记刘处让载酒夜访范延光，称契丹使者要求后晋交出他，劝其离京避使。范延光担心洛阳的杨光远，请问可否去河阳，刘处让表示可以。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "d2ef9018-3a94-5a24-a258-6812e7d2bf36"}, {"title": "杨光远贪图范延光财货，请求除掉他，石敬瑭拒绝", "start_year": 940, "end_year": 940, "time_original": "940年范延光遇害以前，具体月日未载", "dynasty": "五代十国", "description": "《资治通鉴》说，杨光远贪图范延光的财货，又担心他成为子孙的隐患，奏称范延光可能逃入敌国，应及早除掉。石敬瑭没有批准。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "d30f499d-b4d1-524d-a103-021929379d69"}, {"title": "杨光远请求让范延光住西京，石敬瑭同意", "start_year": 940, "end_year": 940, "time_original": "940年范延光遇害以前，具体月日未载", "dynasty": "五代十国", "description": "杨光远请求让范延光住西京，石敬瑭同意。", "phases": [], "location_name": "西京", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "d1ff7b55-600d-5e03-aa93-0675d1b94e95"}, {"title": "杨光远派杨承贵围范延光宅第，逼他自杀", "start_year": 940, "end_year": 940, "time_original": "940年范延光被推入河以前，具体日期未载", "dynasty": "五代十国", "description": "杨光远派儿子杨承贵带武装士卒围住范延光宅第，逼他自杀。范延光以皇帝所赐铁券及免死承诺质问杨氏父子。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "2d2a0d76-d2fb-5d93-b3fc-6cce51945e12"}, {"title": "杨承贵强迫范延光上马，至浮梁把他推入河中", "start_year": 940, "end_year": 940, "time_original": "940年八月己未；月份据新旧五代史本纪", "dynasty": "五代十国", "description": "杨承贵持刃逼范延光上马，到浮梁后把他推入河中，导致死亡。《新五代史》范延光传写执行者为杨承勋，姓名异说保留。", "phases": [], "location_name": "河阳浮梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "10773ace-e218-5d00-809a-f4e83216c0a8"}, {"title": "杨光远谎报范延光自行投水，石敬瑭知情而未追究", "start_year": 940, "end_year": 940, "time_original": "940年八月范延光死亡以后，具体日期未载", "dynasty": "五代十国", "description": "杨光远上奏称范延光自行投水。《资治通鉴》记石敬瑭知道实情，但畏惧杨光远的强势，不敢追究。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "9ceb2328-87ad-57d1-898d-da2415a6911f"}, {"title": "石敬瑭为范延光停朝，追赠太师", "start_year": 940, "end_year": 940, "time_original": "940年八月范延光死亡以后，具体日期未载", "dynasty": "五代十国", "description": "石敬瑭为范延光停朝，追赠太师。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "4f1da612-8b61-5609-bc18-ad38b15d6abe"}, {"title": "李璟坚持辞去太子，李昪准许，仍按太子礼致笺", "start_year": 940, "end_year": 940, "time_original": "940年九月乙丑", "dynasty": "五代十国", "description": "李璟坚持辞去太子，李昪在乙丑准许，并命朝内外致笺仍按太子礼。", "phases": [], "location_name": "五代十国", "location_modern_name"