ocation_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "8d898b22-1902-5905-a9b4-0d3f127bef98"}, {"title": "史书记李澣屡有酒后失当，石敬瑭不喜欢他", "start_year": null, "end_year": null, "time_original": "940年九月撤销学士职务以前的作风概述，具体起止年月未载", "dynasty": "五代十国", "description": "《资治通鉴》评价李澣轻薄，并说他多次酒后失当，石敬瑭不喜欢他。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "de758e8a-f2af-5e8d-8d07-1effe541bcb1"}, {"title": "石敬瑭撤销翰林学士，将事务并入中书舍人", "start_year": 940, "end_year": 940, "time_original": "940年九月丙子", "dynasty": "五代十国", "description": "石敬瑭撤销翰林学士，将相关事务并入中书舍人。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "7e4eff3d-bc97-54f9-8bf9-1997a2f11d14"}, {"title": "李澣调任吏部员外郎", "start_year": 940, "end_year": 940, "time_original": "940年九月丁丑条下；月份依前后主书官制调整对照", "dynasty": "五代十国", "description": "《旧五代史》记，撤销翰林学士院后，李浣调任吏部员外郎。本批按同期翰林学士职务与任官顺序识别为《资治通鉴》的李澣，保留字形说明。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "3e70e30c-9967-55fc-b918-b9d649238963"}, {"title": "杨光远入朝，石敬瑭以酬功为由任其将校为刺史", "start_year": 940, "end_year": 940, "time_original": "940年九月甲申调任以前，具体日期未载", "dynasty": "五代十国", "description": "杨光远入朝，石敬瑭打算把他调到别镇，称围魏时其部下有功未赏，应各给一州，随后任其数名将校为刺史。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c596d46b-4a1d-520f-be68-340ac2baa4d5"}, {"title": "石敬瑭调杨光远为平卢节